actions.script:
// Delete ALL existing authz for this role+module combo (seed data + custom)
def existingList = ec.entity.find("moqui.security.ArtifactAuthz")
    .condition("userGroupId", userGroupId)
    .condition("artifactGroupId", artifactGroupId)
    .list()
for (def existing : existingList) { existing.delete() }

String authzId = "ZC_${userGroupId}_${artifactGroupId}".toString()
if (accessLevel == "VIEW") {
    ec.entity.makeValue("moqui.security.ArtifactAuthz").setAll([
        artifactAuthzId: authzId, userGroupId: userGroupId,
        artifactGroupId: artifactGroupId,
        authzTypeEnumId: "AUTHZT_ALLOW", authzActionEnumId: "AUTHZA_VIEW"
    ]).createOrUpdate()
} else if (accessLevel == "FULL") {
    ec.entity.makeValue("moqui.security.ArtifactAuthz").setAll([
        artifactAuthzId: authzId, userGroupId: userGroupId,
        artifactGroupId: artifactGroupId,
        authzTypeEnumId: "AUTHZT_ALLOW", authzActionEnumId: "AUTHZA_ALL"
    ]).createOrUpdate()
}

if (userId == ec.user.userId) return
def myT = ec.entity.find("moqui.security.UserGroupMember").condition("userId", ec.user.userId).list()*.userGroupId.findAll{ it?.startsWith('TENANT_') }
def authorized = false
if (myT) {
    def theirs = ec.entity.find("moqui.security.UserGroupMember").condition("userId", userId).list()*.userGroupId
    authorized = theirs.any { myT.contains(it) }
}
if (!authorized) ec.message.addError('Not authorized to manage a user outside your organization')

if.script:
def adminUserIds = ec.entity.find("moqui.security.UserGroupMember")
        .condition("userGroupId", userGroupId)
        .conditionDate("fromDate", "thruDate", ec.user.nowTimestamp)
        .list()*.userId.unique()
def others = adminUserIds.findAll { it != userId }
if (userGroupId == 'ZENITH_ADMIN' && others) {
    // A user's organisation membership is authoritatively the PrtEmployee/Member/Agent ->
    // OrgInternal party relationship (what setup#UserOrganizationInfo uses); the TENANT_
    // group is a secondary signal that some accounts have and some (e.g. Google admins)
    // do not. Use the UNION so no real tenant admin is ever mis-scoped as org-less.
    def orgsOf = { uid ->
        def pid = ec.entity.find("moqui.security.UserAccount").condition("userId", uid).one()?.partyId
        if (!pid) return ([] as Set)
        ec.entity.find("mantle.party.PartyRelationship").condition("fromPartyId", pid)
                .condition("toRoleTypeId", "OrgInternal")
                .conditionDate("fromDate", "thruDate", ec.user.nowTimestamp)
                .list()*.toPartyId as Set
    }
    def tenantsOf = { uid -> ec.entity.find("moqui.security.UserGroupMember").condition("userId", uid)
            .list()*.userGroupId.findAll { it != null && it.startsWith('TENANT_') } as Set }
    def tgtOrgs = orgsOf(userId); def tgtTenants = tenantsOf(userId)
    if (tgtOrgs || tgtTenants) {
        // scope to other admins in the SAME organisation (shared OrgInternal org OR TENANT_ group)
        others = others.findAll { o -> orgsOf(o).any { tgtOrgs.contains(it) } || tenantsOf(o).any { tgtTenants.contains(it) } }
    } else {
        // truly org-less admin: its scope is the set of other org-less admins
        others = others.findAll { o -> orgsOf(o).isEmpty() && tenantsOf(o).isEmpty() }
    }
}
if (!others) ec.message.addError("Cannot remove the last administrator role — this organisation must keep at least one administrator. Assign an admin role to another user first.")

actions.script:
userFullName = userFullName.trim()
def ua = ec.entity.find("moqui.security.UserAccount").condition("userId", userId).forUpdate(true).one()
if (ua == null) { ec.message.addError("That user no longer exists."); return }
def changedUser = (username != ua.username)
def changedName = (userFullName != ua.userFullName)
if (changedUser) {
    def taken = ec.entity.find("moqui.security.UserAccount").condition("username", username).list().any { it.userId != userId }
    if (taken) { ec.message.addError("Username '" + username + "' is already in use. Please choose another."); return }
}
boolean _d = ec.artifactExecution.disableAuthz()
try {
    // Billing reads the linked person. Re-saving also repairs earlier account-only renames.
    def person = ua.partyId ? ec.entity.find("mantle.party.Person").condition("partyId", ua.partyId).forUpdate(true).one() : null
    def changedPerson = person && [person.firstName, person.lastName].findAll { it }.join(' ') != userFullName
    if (!changedUser && !changedName && !changedPerson) {
        ec.message.addMessage("No changes to save."); return
    }
    if (changedUser || changedName) {
        ua.username = username
        ua.userFullName = userFullName
        ua.update()
    }
    if (changedPerson) {
        int lastSpace = userFullName.lastIndexOf(' ')
        person.firstName = lastSpace < 0 ? userFullName : userFullName.substring(0, lastSpace)
        person.lastName = lastSpace < 0 ? null : userFullName.substring(lastSpace + 1)
        person.update()
    }
    ec.message.addMessage("User details updated.")
} finally { if (!_d) ec.artifactExecution.enableAuthz() }

def uacct = ec.entity.find("moqui.security.UserAccount").condition("userId", userId).one()
if (uacct == null) { ec.message.addError("That user no longer exists."); return }
def pid = uacct.partyId
boolean _d = ec.artifactExecution.disableAuthz()
try {
    // the user's own login-scoped records
    ec.entity.find("moqui.security.UserGroupMember").condition("userId", userId).deleteAll()
    ec.entity.find("moqui.security.UserPreference").condition("userId", userId).deleteAll()
    uacct.delete()
    // person/party: FK-fails (and rolls the whole transaction back) if the party has ANY
    // business link, which is exactly the guard we want — only a truly unused party deletes.
    if (pid) {
        // ZE-USERS delete f/u: first remove the account's AUTO-created org-membership relationship
        // (PrtEmployee/PrtAgent/PrtMember -> OrgInternal, added by createUser [ZE-USERS-001] so the
        // user can log in). That is account SETUP, not business activity — leaving it undeleted made
        // EVERY UI-created user permanently undeletable (the Party delete FK-failed on it, so a fresh
        // no-activity user always got "has activity, disable instead"). Any OTHER FK child (orders,
        // bills, contacts, party_identification, ...) still fails the Party delete below and rolls the
        // whole thing back, so a user with real activity is still correctly refused + preserved.
        ec.entity.find("mantle.party.PartyRelationship").condition("fromPartyId", pid)
                .condition("relationshipTypeEnumId", "in", ["PrtEmployee", "PrtAgent", "PrtMember"])
                .condition("toRoleTypeId", "OrgInternal").deleteAll()
        ec.entity.find("mantle.party.PartyRole").condition("partyId", pid).deleteAll()
        ec.entity.find("mantle.party.Person").condition("partyId", pid).one()?.delete()
        ec.entity.find("mantle.party.Party").condition("partyId", pid).one()?.delete()
    }
    ec.message.addMessage("User deleted. Their username is now free to reuse.")
} catch (Exception e) {
    ec.message.addError("This user has activity in the system (transactions, contacts or history) and can't be permanently deleted. Disable the account instead — it blocks sign-in but keeps their records.")
} finally { if (!_d) ec.artifactExecution.enableAuthz() }
